<script setup>
import {computed,ref} from 'vue';import {useInvestigation,events,sources,time} from './useInvestigation';import EvidenceDetail from './EvidenceDetail.vue';import ChatContent from './ChatContent.vue';
const {state,select}=useInvestigation();const start=ref(90),span=ref(180),all=ref(false);
const rows=computed(()=>sources.map(s=>({...s,items:events.filter(e=>e.source===s.id&&(all.value||['EV-106','EV-107','EV-108','EV-110','EV-111','EV-112','GAP-01'].includes(e.id))&&(e.end??e.t)>=start.value&&e.t<=start.value+span.value)})));
const x=t=>Math.max(0,Math.min(100,(t-start.value)/span.value*100));
function pan(d){start.value=Math.max(0,Math.min(360-span.value,start.value+d*30))}
</script><template><div class="studio-layout"><header class="studio-header"><span class="wordmark">TRACE<span class="brand-square"></span></span><span class="studio-breadcrumb">תחקירים <span>/</span> האירוע של T-041</span><span>05.10.2026 · נתונים מדומים</span></header><div class="studio-body"><aside class="studio-assistant"><div class="studio-assistant-title"><span class="assistant-dot"></span><h2>עוזר התחקיר</h2></div><ChatContent/></aside><main class="studio-workspace"><div class="studio-title"><div><span class="eyeline">תמונה אחת מכל המקורות</span><h1>רצף האירוע</h1></div><label><input type="checkbox" v-model="all"/>גם פעילות שגרתית</label></div><div class="studio-time"><div dir="ltr"><button @click="pan(-1)" :disabled="start===0" aria-label="Earlier window">←</button><bdi>{{time(start)}} — {{time(start+span)}}</bdi><button @click="pan(1)" :disabled="start+span===360" aria-label="Later window">→</button></div><select v-model.number="span" @change="start=Math.min(start,360-span)" aria-label="משך חלון"><option :value="120">2 דקות</option><option :value="180">3 דקות</option><option :value="360">כל האירוע</option></select></div><div class="studio-timeline-scroll"><div class="studio-timeline"><div class="studio-axis"><span>מערכת</span><div dir="ltr"><bdi v-for="n in 5" :key="n">{{time(start+(n-1)*span/4)}}</bdi></div></div><div v-for="s in rows" :key="s.id" class="studio-row"><div class="studio-system"><i :style="{background:s.color}"></i><strong>{{s.system}}</strong><small>{{s.name}}</small></div><div class="studio-track" dir="ltr"><button v-for="(e,i) in s.items" :key="e.id" :class="['studio-mark',{duration:e.end,active:state.selected?.id===e.id,alert:e.severity==='critical'}]" :style="{left:x(e.t)+'%',width:e.end?Math.max(.5,x(e.end)-x(e.t))+'%':'12px',top:(all?24+(i%2)*31:34)+'px'}" @click="select(e.id)" :aria-label="e.title" :title="e.title"><span :class="{'left-label':x(e.t)>65}">{{e.title}}</span><i></i></button></div></div></div></div><section class="studio-detail"><EvidenceDetail v-if="state.selected" :event="state.selected" compact/><div v-else class="studio-empty"><span>↖</span><p>בחרו אירוע. הפרטים יופיעו כאן.</p><small>הציר נשאר פשוט. העומק נפתח כשצריך.</small></div></section></main></div></div></template>